import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const publicWasmDir = path.join(__dirname, '../public/wasm');
const grammarDir = path.join(publicWasmDir, 'grammars');
const outDir = path.join(__dirname, '../src/generated');

const wasmFiles = {
    core: path.join(publicWasmDir, 'tree-sitter.wasm'),
    yaml: path.join(grammarDir, 'yaml.wasm'),
    json: path.join(grammarDir, 'json.wasm'),
    hcl: path.join(grammarDir, 'hcl.wasm')
};

fs.mkdirSync(outDir, { recursive: true });

let tsContent = `/**
 * AUTO-GENERATED IN-MEMORY WASM ASSETS
 * Generated by scripts/bundle-wasm.js - DO NOT EDIT DIRECTLY.
 */

`;

let totalSize = 0;
for (const [key, filePath] of Object.entries(wasmFiles)) {
    if (!fs.existsSync(filePath)) {
        console.error(`[ERROR] WASM file not found: ${filePath}`);
        process.exit(1);
    }
    const buf = fs.readFileSync(filePath);
    totalSize += buf.length;
    const base64 = buf.toString('base64');
    const constName = `WASM_${key.toUpperCase()}`;
    tsContent += `/** ${key} wasm (${(buf.length / 1024).toFixed(1)} KB) */\n`;
    tsContent += `export const ${constName}: Buffer = Buffer.from(\n    '${base64}',\n    'base64'\n);\n\n`;
}

const targetTsFile = path.join(outDir, 'embedded-wasm.ts');
fs.writeFileSync(targetTsFile, tsContent, 'utf-8');

console.log(`⚡ [BUNDLE_WASM] Generated ${targetTsFile}`);
console.log(`📦 [BUNDLE_WASM] Total embedded WASM payload: ${(totalSize / 1024).toFixed(1)} KB across 4 grammars.`);
